import ballerina/io;

function container() returns int[] {
    io:println("container");
    return [10, 20];
}

function key() returns int {
    io:println("key");
    return 1;
}

function mapContainer() returns map<int> {
    io:println("map");
    return {a: 1};
}

function mapKey() returns string {
    io:println("mapKey");
    return "a";
}

public function main() {
    int x = container()[key()];
    io:println(x);
    int? y = mapContainer()[mapKey()];
    io:println(y);
}

